INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (357, 1, '프로젝트 네트워크의 기본 성질', 'OpenStack 에서 프로젝트가 만든 **프로젝트 네트워크** 는 기본적으로 어떤 성질일까요?', '다른 팀의 서버와 섞이면 곤란하겠죠.', NULL, NULL, '[]', 'choice', '["모든 프로젝트가 자동으로 공유해서 함께 쓴다", "관리자만 볼 수 있고 소유 프로젝트도 쓸 수 없다", "다른 프로젝트와 공유되지 않고 완전히 격리되어 있다", "서버가 하나도 없을 때만 만들 수 있다"]', 2, '공식 문서는 프로젝트 네트워크가 기본적으로 다른 프로젝트와 공유되지 않고 완전히 격리되어 있다고 설명합니다.', NULL, NULL, NULL, '[{"title": "Neutron 네트워킹 소개", "url": "https://docs.openstack.org/neutron/latest/admin/intro-os-networking.html"}]'),
  (357, 2, '서브넷이란', '**서브넷(subnet)** 은 무엇일까요?', '주소를 나눠 주는 범위를 떠올려 보세요.', NULL, NULL, '[]', 'choice', '["서버의 CPU 를 나눠 쓰는 단위 하나", "IP 주소 한 묶음과 설정으로, 포트에 주소를 준다", "서버 사이의 방화벽 규칙을 모아 둔 목록", "서버에 붙이는 디스크 볼륨의 한 종류"]', 1, '서브넷은 IP 주소 블록과 관련 설정을 담고, 네트워크에 새 포트가 만들어질 때 거기서 주소를 가져다 줍니다.', NULL, NULL, NULL, '[{"title": "Neutron 네트워킹 소개", "url": "https://docs.openstack.org/neutron/latest/admin/intro-os-networking.html"}]'),
  (357, 3, '포트란', 'Neutron 의 **포트(port)** 는 무엇일까요?', '서버의 랜카드를 가상 네트워크에 꽂는 곳이에요.', NULL, NULL, '[]', 'choice', '["서버의 NIC 같은 장치를 가상 네트워크에 잇는 지점", "네트워크 안에 열어 둔 TCP 포트 번호 하나", "서버가 쓸 수 있는 디스크의 한 구획", "사용자가 로그인할 때 쓰는 접속 창구"]', 0, '공식 문서는 포트를 "가상 서버의 NIC 같은 단일 장치를 가상 네트워크에 연결하는 지점"이라고 설명합니다. 포트 번호(80, 443 같은 TCP 포트)와는 다른 말입니다.', NULL, NULL, NULL, '[{"title": "Neutron 네트워킹 소개", "url": "https://docs.openstack.org/neutron/latest/admin/intro-os-networking.html"}]'),
  (357, 4, '포트에 기록되는 것', '포트는 서버가 네트워크에 연결된 정보를 담습니다. 포트에 기록되는 주소로 알맞은 것은 무엇일까요?', '네트워크 카드의 주소와 IP 를 떠올려 보세요.', NULL, NULL, '[]', 'choice', '["서버의 이메일 주소와 URL", "서버의 디스크 일련번호와 용량", "서버 사용자의 로그인 이름과 암호", "MAC 주소와 IP 주소"]', 3, '포트는 연결된 장치의 MAC 주소와 IP 주소를 기록합니다. 서버에 NIC 가 둘이면 포트도 두 개가 됩니다.', NULL, NULL, NULL, '[{"title": "Neutron 네트워킹 소개", "url": "https://docs.openstack.org/neutron/latest/admin/intro-os-networking.html"}]'),
  (357, 5, '가상 라우터가 하는 일', 'Neutron 의 **라우터** 가 해 주는 일로 알맞은 것은 무엇일까요?', '서로 다른 네트워크 사이를 이어 주는 장치예요.', NULL, NULL, '[]', 'choice', '["서버의 부팅 이미지를 내려받아 저장하는 일", "사용자가 로그인할 때 비밀번호를 검증하는 일", "셀프서비스 네트워크와 프로바이더 네트워크 사이 라우팅과 NAT", "서버의 CPU 와 메모리를 크기별로 나눠 주는 일"]', 2, '공식 문서는 라우터를 셀프서비스 네트워크와 프로바이더 네트워크 사이(그리고 셀프서비스 네트워크끼리)의 라우팅과 NAT 같은 가상 3계층 서비스를 제공하는 것이라고 설명합니다.', NULL, NULL, NULL, '[{"title": "Neutron 네트워킹 소개", "url": "https://docs.openstack.org/neutron/latest/admin/intro-os-networking.html"}]'),
  (357, 6, 'Neutron 의 역할', '**Neutron** 은 OpenStack 에서 어떤 일을 맡을까요?', '서버의 "연결"을 맡는 서비스예요.', NULL, NULL, '[]', 'choice', '["서버를 만들고 시작·중지하는 컴퓨트 일을 도맡아 한다", "API 로 네트워크 연결을 정의하고 라우팅·NAT 등을 관리한다", "서버에 붙이는 영구 디스크 볼륨을 만들고 관리해 준다", "서버를 만들 때 쓰는 디스크 이미지를 등록하고 보관한다"]', 1, 'Neutron 은 클라우드의 네트워크 연결과 주소 지정을 정의하는 API 를 제공하고, L3 포워딩·NAT·방화벽·VPN 같은 네트워크 서비스를 관리하게 해 줍니다.', NULL, NULL, NULL, '[{"title": "Neutron 네트워킹 소개", "url": "https://docs.openstack.org/neutron/latest/admin/intro-os-networking.html"}]'),
  (357, 7, '스위치와 라우터의 차이', '네트워크 장비 중 **스위치** 와 **라우터** 의 차이로 알맞은 것은 무엇일까요?', '한쪽은 같은 네트워크 안, 한쪽은 네트워크 사이예요.', NULL, NULL, '[]', 'choice', '["스위치는 같은 네트워크 안에서 이더넷 주소로, 라우터는 네트워크 사이를 IP 주소로 전달한다", "스위치는 네트워크 사이를 IP 주소로, 라우터는 같은 네트워크 안에서 이더넷 주소로 전달한다", "스위치와 라우터는 이름만 다른 같은 장비라서 하는 일이 서로 완전히 똑같다", "스위치는 접속 암호를 검사하고 라우터는 서버 파일을 저장하는 장비다"]', 0, 'Neutron 문서는 스위치가 같은 2계층 네트워크의 호스트를 이더넷 주소로 이어 주고, 라우터는 서로 연결되지 않은 네트워크까지 포함해 3계층 네트워크 사이로 IP 주소를 보고 패킷을 옮긴다고 설명합니다.', NULL, NULL, NULL, '[{"title": "Neutron 네트워크 구성 요소", "url": "https://docs.openstack.org/neutron/latest/admin/intro-network-components.html"}]'),
  (357, 8, '방화벽이 하는 일', '네트워크에서 **방화벽** 은 어떤 일을 할까요?', '집 문의 출입 규칙과 비슷해요.', NULL, NULL, '[]', 'choice', '["모든 서버의 운영체제를 자동으로 새 버전으로 바꾼다", "서버가 보내는 이메일을 모아 하나의 파일로 저장한다", "서버의 전원이 꺼지면 자동으로 다시 켜 준다", "IP·포트·연결 상태 조건으로 드나드는 트래픽을 규제한다"]', 3, '공식 문서는 방화벽을 호스트나 네트워크로 드나드는 트래픽을 규제하는 것으로 설명하며, IP 주소·포트·연결 상태 같은 기준으로 걸러낼 수 있다고 합니다.', NULL, NULL, NULL, '[{"title": "Neutron 네트워크 구성 요소", "url": "https://docs.openstack.org/neutron/latest/admin/intro-network-components.html"}]'),
  (357, 9, '로드 밸런서가 하는 일', '**로드 밸런서** 는 어떤 일을 할까요?', '한 서버에만 손님이 몰리면 힘들겠죠.', NULL, NULL, '[]', 'choice', '["서버의 디스크 데이터를 자동으로 하나로 합쳐 준다", "서버 한 대의 CPU 속도를 임의로 높여 준다", "들어오는 트래픽을 여러 서버에 나눠서 한 서버에 몰리지 않게 한다", "서버를 만들 때 이름을 겹치지 않게 지어 준다"]', 2, '로드 밸런서는 트래픽을 여러 서버에 나눠 한 서버가 과부하되지 않게 하고, 단일 장애 지점을 줄이며 응답 시간을 개선합니다.', NULL, NULL, NULL, '[{"title": "Neutron 네트워크 구성 요소", "url": "https://docs.openstack.org/neutron/latest/admin/intro-network-components.html"}]'),
  (357, 10, '네트워크 목록 보기', '`openstack` 명령으로 **네트워크 목록** 을 보려고 합니다. 빈칸을 채우세요.', '네트워크를 영어로 쓰면 돼요.', NULL, NULL, '[]', 'fill', '["network", "net", "lan", "vnet"]', NULL, '`openstack network list` 는 프로젝트가 볼 수 있는 네트워크 목록을 보여 줍니다.', '[0]', 'openstack {0} list', NULL, '[{"title": "Neutron 네트워킹 소개", "url": "https://docs.openstack.org/neutron/latest/admin/intro-os-networking.html"}]'),
  (357, 11, '라우터 목록 보기', '`openstack` 명령으로 **라우터 목록** 을 보려고 합니다. 빈칸을 채우세요.', '길을 이어 주는 장치를 영어로 쓰면 돼요.', NULL, NULL, '[]', 'fill', '["router", "gateway", "route", "switch"]', NULL, '`openstack router list` 는 프로젝트의 가상 라우터 목록을 보여 줍니다.', '[0]', 'openstack {0} list', NULL, '[{"title": "Neutron 네트워킹 소개", "url": "https://docs.openstack.org/neutron/latest/admin/intro-os-networking.html"}]'),
  (357, 12, '서버를 새 네트워크에 연결하기까지', '새 네트워크를 만들어 서버를 연결하고 밖과 이어 주기까지 큰 줄기 순서입니다. 순서에 맞게 놓아 보세요.', '네트워크 → 주소 범위 → 라우터 → 연결 → 서버 순서예요.', NULL, NULL, '[]', 'order', '["네트워크를 만든다", "그 네트워크에 서브넷(주소 블록)을 만든다", "라우터를 만든다", "라우터를 서브넷에 연결한다", "그 네트워크를 지정해 서버를 만든다"]', NULL, '네트워크를 만들고, 거기에 쓸 주소 범위(서브넷)를 정하고, 라우터를 만들어 서브넷에 연결한 뒤, 서버를 그 네트워크에 연결해 만듭니다. 환경에 따라 이미 있는 네트워크를 쓸 수도 있습니다.', '[0, 1, 2, 3, 4]', NULL, NULL, '[{"title": "Neutron 네트워킹 소개", "url": "https://docs.openstack.org/neutron/latest/admin/intro-os-networking.html"}]');
